def pack(objs, inp, dr, H=10, W=10):
    shifted={}
    for k,o in enumerate(objs):
        col=inp[o[0][0]][o[0][1]]
        cells=[(r+dr,c) for r,c in o]
        if all(0<=r<H for r,c in cells):
            minr=min(r for r,c in cells); minc=min(c for r,c in cells)
            shifted[k]=(col,sorted((r-minr,c-minc) for r,c in cells), minr)
    order=sorted(range(len(objs)), key=lambda k: -max(c for r,c in objs[k]))
    grid=[[0]*W for _ in range(H)]
    for k in order:
        if k not in shifted: continue
        col,rel,minr=shifted[k]
        maxdc=max(c for r,c in rel)
        L=9-maxdc
        while L>=0:
            cand=[(minr+r, L+c) for r,c in rel]
            if all(0<=r<H and 0<=c<W and grid[r][c]==0 for r,c in cand):
                for r,c in cand: grid[r][c]=col
                break
            L-=1
        else:
            raise ValueError(f"no fit obj {k}")
    return grid

